class Solution { public int minNumberOfSemesters(int n,int[][] relations,int k){int[] prerequisite=new int[n];for(int[] relation:relations)prerequisite[relation[1]-1]|=1<<(relation[0]-1);int total=1<<n,inf=100;int[] dp=new int[total];Arrays.fill(dp,inf);dp[0]=0;for(int mask=0;mask<total;mask++){if(dp[mask]==inf)continue;int available=0;for(int course=0;course<n;course++)if((mask&(1<<course))==0&&(prerequisite[course]&mask)==prerequisite[course])available|=1<<course;if(Integer.bitCount(available)<=k)dp[mask|available]=Math.min(dp[mask|available],dp[mask]+1);else for(int subset=available;subset>0;subset=(subset-1)&available)if(Integer.bitCount(subset)==k)dp[mask|subset]=Math.min(dp[mask|subset],dp[mask]+1);}return dp[total-1];} }
